package com.studentcheckassist;
import android.app.*;import android.content.*;import android.os.*;
public class AlarmReceiver extends BroadcastReceiver { public void onReceive(Context c,Intent i){String title=i.getStringExtra("title"); String ch="student_checks"; NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE); if(Build.VERSION.SDK_INT>=26)nm.createNotificationChannel(new NotificationChannel(ch,"Student Checks",NotificationManager.IMPORTANCE_HIGH)); Intent open=new Intent(c,MainActivity.class); PendingIntent pi=PendingIntent.getActivity(c,0,open,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT); Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,ch):new Notification.Builder(c); b.setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("Student Check Assist").setContentText(title==null?"Check reminder":title).setAutoCancel(true).setContentIntent(pi); nm.notify((int)System.currentTimeMillis(),b.build()); }}
